            "row_count": 0,
            "total_cents": 0,
            "first_day": None,
            "last_day": None
        }

    row_count = 0
    total_cents = 0
    first_day: Optional[str] = None
    last_day: Optional[str] = None

    def is_valid_date(day: str) -> bool:
        """Check if day string is a valid YYYY-MM-DD date."""
        try:
            year, month, day_num = int(day[:4]), int(day[5:7]), int(day[8:10])
            return 1 <= month <= 12 and 1 <= day_num <= calendar.monthrange(year, month)[1]
        except (ValueError, AttributeError):
            return False

    for row in data:
        if not isinstance(row, dict):
            raise ValueError(f"Row must be an object: {row}")

        tenant = row.get('tenant')
        amount_cents = row.get('amount_cents')
        day = row.get('day')

        # Check required fields
        if tenant is None or amount_cents is None or day is None:
            raise ValueError(f"Row missing required fields: {row}")

        # Check tenant is nonempty string
        if not isinstance(tenant, str) or len(tenant) == 0:
            raise ValueError(f"tenant must be nonempty string: {tenant}")

        # Check amount_cents is integer (not boolean, not string)
        if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
            raise ValueError(f"amount_cents must be integer: {amount_cents}")

        # Check day is valid YYYY-MM-DD
        if not is_valid_date(day):
            raise ValueError(f"Invalid day format: {day}")

        # Valid row - update totals
        row_count += 1
        total_cents += amount_cents

        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        "row_count": row_count,
        "total_cents": total_cents,
        "first_day": first_day,
        "last_day": last_day
    }
